  "descripcion": "La llana de magnesio Marshalltown es una herramienta de acabado usada en la construcción, especialmente para trabajar con concreto. A diferencia de las llanas de acero, las de magnesio son ligeras y resistentes a la corrosión , lo que las hace ideales para flotar la superficie del concreto. La llana con las especificaciones que mencionaste es de 406 mm de largo y 79 mm de ancho, con la punta redondeada .\nCARACTERISTICAS:\n• Material : Magnesio extruido . Es un material ligero y duradero que reduce la fatiga del operario y es resistente al óxido.\n• Dimensiones : 406 x 79 mm (16 x 3.125 pulgadas). Este tamaño es versátil para trabajos de mediano y gran tamaño.\n• Punta : Redonda . Este diseño previene que la punta de la herramienta se clave en el concreto, lo cual podría dejar marcas indeseadas.\nUSO:\n• Nivelación inicial : Se usa para nivelar y alisar el concreto recién vertido después de que se haya enrasado.\n• Flotado : Permite llevar la lechada (la mezcla de agua y cemento) a la superficie. Esto cierra la porosidad del concreto y prepara la superficie para el acabado final, como el llanado con llana de acero.\n• Reducción de burbujas : El movimiento de la llana ayuda a eliminar el aire atrapado en la mezcla, lo que mejora la resistencia y la densidad del concreto.\n• Ventajas : Gracias al magnesio, la llana no se calienta tan rápido como una de acero, lo que ayuda a prevenir que el concreto se endurezca prematuramente bajo la herramienta. También deja una textura más abierta en comparación con el acero, que es ideal para superficies que se van a cubrir con alfombra o baldosas.",
