  "categoria": "Compresores",
  "subcategoria": "",
  "codigo": "C50M",
  "descripcion": "Potencia maxima del motor: 2 HP\nPresion: 8/116 BAR\nRevoluciones por minuto: 2850 rpm\nSistema electrico: Monofasico\nCaudal de Aire: 200 Lts/min\nCapacidad del tanque: 50 lts\nRuedas: Si\nPeso bruto: 30 kg\nUn compresor de 50 litros es una máquina versátil y potente que convierte energía mecánica en energía neumática (aire comprimido) para una gran variedad de tareas, tanto en el hogar como en talleres semi-profesionales. El tanque de 50 lts es su característica principal, ya que almacena una cantidad considerable de aire, lo que le permite a la herramienta funcionar por más tiempo sin que el motor se encienda constantemente para rellenar el depósito.",
  "precio": 402458.84,
  "imagen": "https://ss-cnt-001c.esmsv.com/r/content/host2/176cfe0e7cff8ed11a63a13f39623a05//img/products/product-image-5636-480.png"
