  "codigo": "HOMEY-H99",
  "descripcion": "Homey 99 es un tipo de poliuretano altamente\ntermoendurecible, que constituye un excelente material de aislamiento térmico.\nPuede formar una capa continua de aislamiento térmico, asegurando la\ninteracción entre el material de aislamiento térmico y la pared y bloqueando\neficazmente el puente térmico. Se utiliza ampliamente para el aislamiento\ntérmico de tejados y paredes.\nVentajas\n• Buenas\nprestaciones de aislamiento térmico.\n• Excelente\nresistencia al calor y la humedad.\n• Excelente\nrendimiento impermeable/barrera de vapor de agua.\n• Excelente\nresistencia al impacto.\n• Excelente\nresistencia a las grietas.\n• Respetuoso\ncon el medio ambiente.\nUsos básicos:\n• Instalación,\nfijación y aislamiento de ventanas y marcos de puertas\n• Relleno\ny sellado de huecos, juntas de conexión, aberturas y cavidades;\nrespiraderos de aire acondicionado\n• Conexión\nde los materiales de aislamiento y la construcción del techo;\n• Adhesión\ny montaje;\n• Aislamiento\nde las tomas de corriente y de las tuberías de agua; entradas de tuberías\n• Conservación\ndel calor, aislamiento del frío y del ruido;\n• Para\nembalar, envolver los productos preciosos y frágiles, a prueba de\nsacudidas y de presión.\nAplicación:\n• Agite\nel bote de aerosol durante al menos 40 segundos;\n• Limpie\ny humedezca las superficies con un pulverizador de agua antes de la\naplicación;\n• Coloque\nla pistola o el aplicador de plástico en el adaptador. Cuando se instala\nla pistola, hay que apretarla para evitar fugas de aire.\n• Enrosque\nfirmemente el bote en el adaptador y gire el tornillo de ajuste del\ncaudal;\n• Rellena\nlos agujeros y las cavidades.\n• La\nespuma estará libre de pegajosidad en unos 10 minutos;\n• El\nexceso se puede recortar en aproximadamente una hora;\n• La\nespuma fresca puede eliminarse con el limpiador de espuma Homey o con\nacetona.\n• La\nespuma curada sólo puede eliminarse mecánicamente.\nRecomendación de seguridad:\n• No\ny obtener atención médica inmediata;\n• Utilizar\nen zonas bien ventiladas;\n• Llevar\nropa de protección adecuada, guantes y gafas;\n• Mantener\nalejado de la luz solar directa y no exponer a temperaturas superiores a\n50℃;\n• No\nse debe quemar ni perforar incluso después de su uso;\n• Mantener\nalejado del calor, las chispas, las llamas y la electricidad estática;\n• Apague\nlas fuentes de ignición (luz piloto, etc.);\n• Mantener\nfuera del alcance de los niños.\nAlmacenamiento y vida útil:\n12 meses en el envase sin abrir, almacenar a una temperatura\nde +5℃\na +25℃,\nmantener en un lugar fresco, a la sombra y bien ventilado. Mantenga siempre la\nlata con la válvula hacia arriba.\n*STOCK DISPONIBLE JULIO 2025*\nCANTIDADES POR CAJA: 12 UNIDS",
