  "descripcion": "Entrada de aire: Un conector donde se une la manguera del compresor.\nGatillo: Controla el flujo de aire hacia el interior de la herramienta.\nMecanismo interno: El motor o pistón que convierte la energía del aire en movimiento.\nCuerpo: La carcasa que protege los componentes internos.\nRegulador de aire: Permite ajustar la cantidad de aire que entra, controlando así la potencia de la herramienta.\nSalida de aire: Un orificio por donde el aire ya utilizado se expulsa, a menudo con un silenciador.\nVENTAJAS\nGran potencia: Pueden generar una fuerza de torsión o impacto muy alta, superando a la mayoría de las herramientas eléctricas portátiles.\nDurabilidad: Suelen tener un diseño simple y robusto, con menos piezas móviles que sus contrapartes eléctricas, lo que se traduce en una mayor vida útil.\nPeso ligero: Al no necesitar motores eléctricos pesados ni baterías, son más livianas y cómodas para usar durante periodos prolongados.\nMenos riesgo de sobrecalentamiento: A diferencia de las herramientas eléctricas que pueden sobrecalentarse con el uso intensivo, las neumáticas se enfrían con el flujo de aire.",
