  "codigo": "TX-93510002",
  "descripcion": "HOJA PARA CUTTER TRAPEZOIDAL\nMarca: Craftsman\nModelo: Trapezoidal\nCartucho: 50 unidades\nHoja SK-5 de Alta Calidad con Doble Filo\nCompatible con Cutters\nEstuche negro\nLa Hoja Repuesto para Cutter Trapezoidal es la elección ideal para quienes buscan calidad y durabilidad en sus herramientas de corte. Esta hoja de repuesto se presenta en un práctico blister que contiene 50 unidades, asegurando que siempre tengas un repuesto a mano. Su material SK-5 de alta calidad garantiza un corte preciso y eficiente, con un diseño de doble filo que evita roturas, a diferencia de las hojas de menor calidad. Este producto es perfecto para uso profesional, siendo compatible con cutters de hoja fija.",
