  "descripcion": "Características:\n• Lustradora especialmente diseñada para usos industriales continuos, brindando excelentes prestaciones de calidad y uso.\n• Está provista de todos los sistemas de seguridad para soportar los frecuentes maltratos que suelen sufrir estas máquinas.\n• Posee barral con doble comando de accionamiento, con traba.\n• Sistema de seguridad para impedir el funcionamiento con el barral vertical.\n• Ajuste de presión del paño. Rueda central permite el máximo uso del paño.\n• Doble rueda para transporte.\n• Motor asincrónico con doble capacitor, sin escobillas.\nESPECIFICACIONES TÉCNICAS:\nMotor: | 1.5 Hp / 1500 RPM\nAncho de Trabajo: | 51 Cm\nVoltaje: | 220 V\nCable: | 12 Metros Tripolar\nPeso: | 34 Kg.\n** STOCK DISPONIBLE A 7-10 DIAS DESDE EL PEDIDO **",
