  "descripcion": "Rendimiento y versatilidad para el pulido de hormigón\nLa Frida 400 Eco es una pulidora de línea semi profesional, diseñada para brindar un acabado preciso y eficiente en superficies de hormigón, mármol, terrazo y piedra. Su diseño compacto y robusto la convierte en la herramienta ideal para proyectos de pulido y mantenimiento.\nCaracterísticas destacadas:\nSistema de transmisión con 3 correas de aleación de aluminio y cubierta sellada para mayor durabilidad.\nFondo magnético que facilita el cambio rápido de herramientas diamantadas.\nRueda trasera dual independiente que mejora la maniobrabilidad en cualquier tipo de superficie.\nDiseño ergonómico que permite un manejo cómodo y seguro para el operario.\nEspecificaciones técnicas:\nMotor: 5.5 HP\nAncho de Trabajo: 400 mm\nCantidad de cabezales: 3 unidades\nPotencia: 220V\nIntensidad de corriente: 16 amps\nVelocidad de trabajo: 800 RPM\nPeso: 86 kg\nIdeal para profesionales y contratistas que buscan una máquina confiable, eficiente y fácil de operar en distintos proyectos de pulido y preparación de superficies.\n** STOCK DISPONIBLE A 7-10 DIAS DESDE EL PEDIDO **",
