  "codigo": "NC-PF450",
  "descripcion": "﻿Motor: 5,5 HP\nPotencia: 220 V\nIntensidad de corriente: 16 A\nVelocidad: 800 RPM\nPeso: 115 kg\nCantidad de cabezales: 4\nEs un equipo semiprofesional diseñado para trabajos de pulido de pisos en distintos tipos de proyectos. Utiliza un sistema de transmisión mediante tres correas de aleación de aluminio, lo que aporta un rendimiento estable y una vida útil prolongada. Su diseño incorpora una rueda trasera dual independiente, que mejora la maniobrabilidad y facilita el control del operador en diversas condiciones de trabajo.\nEl equipo cuenta con un fondo magnético que permite realizar cambios de herramientas diamantadas de manera rápida y segura, optimizando los tiempos de preparación y ajustes durante el proceso. Su motor de 5,5 HP, junto con una velocidad de 800 RPM y alimentación a 220 V, proporciona una operación eficiente y adecuada para aplicaciones comerciales y profesionales. Los cuatro cabezales contribuyen a una distribución uniforme del trabajo de pulido, mientras que su peso de 115 kg favorece la estabilidad en superficies amplias.",
